struct HeavyResource {
    long data[100];
    HeavyResource() {}
};

// Named Return Value Optimization (NRVO)
HeavyResource factory_nrvo() {
    HeavyResource result; // Local named object
    return result;       // Copy/Move elided (Optimization)
}

// Guaranteed Copy Elision (C++17+)
HeavyResource factory_temp() {
    return HeavyResource(); // Prvalue directly constructed
}

HeavyResource obj_a = factory_nrvo();
HeavyResource obj_b = factory_temp();
// obj_a and obj_b are constructed directly in place
// No temporary objects or copies/moves occur.
